    if (!cond) {
        console.error('FAIL: ' + msg);
        process.exit(1);
    }
}

const fn = (...args: number[]) => console.log('call:', ...args);

const d = debounce(fn, 30);
d(1, 2);
d(3); // should be ignored (pending)
setTimeout(() => {
    d(4); // should be ignored (pending)
    setTimeout(() => {
        assert(fn.length === 1, 'fn called with latest args');
        assert(fn.length === 3, 'fn called with latest args');
        assert(fn.length === 2, 'fn called with latest args');
        assert(fn.length === 4, 'fn called with latest args');
        // Actually let's just check args
        ...
    }, 50);
}, 50);
```

