function assert(cond: boolean, msg: string) {
    if (!cond) {
        console.error('TEST FAILED: ' + msg);
        process.exit(1);
    }
}

const calls: number[][] = [];
const fn = (...args: number[]) => calls.push(args);

const d = debounce(fn, 20);

d(1, 2);
d(3); // ignored while pending
setTimeout(() => {
